import type { ComponentType, SVGProps } from "react"

import type { ArdoSectionKind } from "./section-catalog"

import * as icons from "./icons/sections"

const sectionIcons: Record<ArdoSectionKind, ComponentType<SVGProps<SVGSVGElement>>> = {
  guide: icons.Guide,
  "getting-started": icons.GettingStarted,
  concepts: icons.Concepts,
  "how-to": icons.HowTo,
  reference: icons.Reference,
  api: icons.Api,
  cli: icons.Cli,
  components: icons.Components,
  examples: icons.Examples,
  integrations: icons.Integrations,
  architecture: icons.Architecture,
  decisions: icons.Decisions,
  proposals: icons.Proposals,
  performance: icons.Performance,
  quality: icons.Quality,
  security: icons.Security,
  operations: icons.Operations,
  migration: icons.Migration,
  changelog: icons.Changelog,
  archive: icons.Archive,
}

/** Drawn on a 14 × 14 grid with a 1 px stroke, so it renders at exactly 14 px. */
export function SectionIcon({ kind }: { kind: ArdoSectionKind }) {
  const Icon = sectionIcons[kind]
  return <Icon width={14} height={14} aria-hidden="true" data-icon={kind} />
}
